import re,os,glob
base='library/strength-and-conditioning/supertraining--verkhoshansky'
scope=[l.strip() for l in open('_scope_supertraining_ch5c.txt') if l.strip()]
roots=['/Users/kristinarash/DEV/Flint/staging/library','/Users/kristinarash/SecondBrain/Knowledge/library']
names=set()
for r in roots:
    for p in glob.glob(r+'/**/*.md',recursive=True):
        rel=os.path.relpath(p,r)[:-3]
        parts=rel.split('/')
        names.add(parts[-1]); 
        if len(parts)>=2: names.add('/'.join(parts[-2:]))
heads=['**What it is** —','**Why it works** —','**When to apply** —','**When NOT to apply** —','**Example** —','**Related** —']
bad_words=re.compile(r'prior version|previous version|round[- ]1|round 2|review(er)? (found|flagged|said)|corrected|was changed|fix(ed)? from|NO-GO|per the review|earlier draft',re.I)
for f in scope:
    t=open(os.path.join(base,f)).read()
    issues=[]
    for h in heads:
        if t.count(h)!=1: issues.append(f'header {h} x{t.count(h)}')
    body=t
    for h in heads: body=body.replace(h,'')
    if '—' in body: issues.append(f'em dash x{body.count("—")}')
    for i,l in enumerate(t.split('\n')):
        if l.count('[[')!=l.count(']]'): issues.append(f'wrapped link line {i+1}')
    links=re.findall(r'\[\[([^\]|#]+)',t)
    miss=[l for l in links if l.strip() not in names]
    if miss: issues.append(f'unresolved {miss}')
    for m in bad_words.finditer(t): issues.append(f'history? "{t[max(0,m.start()-40):m.end()+40]}"')
    print(f, len(links), 'links', issues or 'OK')
EOF
